-- Confirmed exam boards and complete specification maps for Geography,
-- Business and Design & Technology. Geography and D&T retain explicit
-- option_required rows until the school confirms the taught choices.
PRAGMA foreign_keys = ON;

INSERT OR IGNORE INTO subjects (id, name, exam_board, specification_code)
VALUES
  ('subject-geography', 'Geography', 'AQA', '8035'),
  ('subject-business', 'Business', 'Edexcel', '1BS0'),
  ('subject-design-technology', 'Design and Technology', 'AQA', '8552');

UPDATE subjects SET exam_board = 'AQA', specification_code = '8035', updated_at = CURRENT_TIMESTAMP WHERE id = 'subject-geography';
UPDATE subjects SET exam_board = 'Edexcel', specification_code = '1BS0', updated_at = CURRENT_TIMESTAMP WHERE id = 'subject-business';
UPDATE subjects SET exam_board = 'AQA', specification_code = '8552', updated_at = CURRENT_TIMESTAMP WHERE id = 'subject-design-technology';

UPDATE student_subjects
SET tier = 'not_applicable',
    options_json = json_set(json_set(json_set(json_set(json_set(options_json,
      '$.configuration', 'confirmed'), '$.livingWorldOption', 'TBC'), '$.ukLandscapeOptions', 'TBC'),
      '$.resourceOption', 'TBC'), '$.caseStudies', 'TBC'),
    updated_at = CURRENT_TIMESTAMP
WHERE subject_id = 'subject-geography';

UPDATE student_subjects
SET tier = 'not_applicable', options_json = json_set(options_json, '$.configuration', 'confirmed'), updated_at = CURRENT_TIMESTAMP
WHERE subject_id = 'subject-business';

UPDATE student_subjects
SET tier = 'not_applicable',
    options_json = json_set(json_set(options_json, '$.configuration', 'confirmed'), '$.specialistMaterial', 'TBC'),
    updated_at = CURRENT_TIMESTAMP
WHERE subject_id = 'subject-design-technology';

UPDATE topics SET active = 0, updated_at = CURRENT_TIMESTAMP
WHERE subject_id IN ('subject-geography', 'subject-business', 'subject-design-technology');

DELETE FROM course_components WHERE subject_id IN ('subject-geography', 'subject-business', 'subject-design-technology');

