  ('dt-investigation', 'subject-design-technology', 'dt-designing-making', 'Paper 1 Section C and NEA', 'Investigation and design possibilities', 'Primary and secondary research; user needs and context; product analysis; environmental, social and economic challenges; work of designers and companies.', 'AQA', '8552', 'both', 4, 1, 'https://www.aqa.org.uk/subjects/design-and-technology/gcse/design-and-technology-8552/specification/subject-content/designing-and-making-principles', 'AQA 8552', 'common'),
  ('dt-brief-specification', 'subject-design-technology', 'dt-designing-making', 'Paper 1 Section C and NEA', 'Design brief and specification', 'Turning research into a focused brief; measurable user-centred specification criteria; constraints, function, aesthetics, cost, safety and sustainability.', 'AQA', '8552', 'both', 3, 1, 'https://www.aqa.org.uk/subjects/design-and-technology/gcse/design-and-technology-8552/specification/subject-content/designing-and-making-principles', 'AQA 8552', 'common'),
  ('dt-ideas', 'subject-design-technology', 'dt-designing-making', 'Paper 1 Section C and NEA', 'Generating and communicating ideas', 'Iterative and collaborative strategies; avoiding design fixation; annotated sketches, modelling, CAD and technical communication for different audiences.', 'AQA', '8552', 'both', 4, 1, 'https://www.aqa.org.uk/subjects/design-and-technology/gcse/design-and-technology-8552/specification/subject-content/designing-and-making-principles', 'AQA 8552', 'common'),
  ('dt-development', 'subject-design-technology', 'dt-designing-making', 'Paper 1 Section C and NEA', 'Developing design ideas', 'Using modelling, testing and user feedback; selecting materials and components; resolving dimensions, construction, manufacture and sustainability iteratively.', 'AQA', '8552', 'both', 4, 1, 'https://www.aqa.org.uk/subjects/design-and-technology/gcse/design-and-technology-8552/specification/subject-content/designing-and-making-principles', 'AQA 8552', 'common'),
