INSERT INTO subject_revision_guides
  (subject_id, exam_summary, assessment_objectives_json, exam_tips_json, specification_url, assessment_resources_url, provisional, verified_at)
VALUES
  ('subject-geography', 'AQA GCSE Geography 8035: Paper 1 Living with the physical environment (1 hour 30 minutes, 88 marks, 35%); Paper 2 Challenges in the human environment (1 hour 30 minutes, 88 marks, 35%); Paper 3 Geographical applications (1 hour 30 minutes, 76 marks, 30%). Optional units and named case studies still need confirming.', '["AO1: demonstrate knowledge of locations, places, processes, environments and scales","AO2: show geographical understanding of concepts and interrelationships","AO3: apply knowledge and understanding to interpret, analyse and evaluate information and issues","AO4: select, adapt and use geographical skills and techniques"]', '["Learn precise named-case-study evidence rather than generic stories","Develop process chains using because, therefore and this means","Use figures, units and map or graph evidence whenever a resource is supplied","For evaluate or assess questions, compare alternatives and finish with a supported judgement","Practise fieldwork methods, limitations, conclusions and improvements for both enquiries"]', 'https://www.aqa.org.uk/subjects/geography/gcse/geography-8035/specification', 'https://www.aqa.org.uk/subjects/geography/gcse/geography-8035/assessment-resources', 1, '2026-09-28'),
  ('subject-business', 'Pearson Edexcel GCSE Business 1BS0: Paper 1 Investigating small business and Paper 2 Building a business are each 1 hour 45 minutes, 90 marks and 50%. Both include calculations, multiple-choice, short-answer and extended-writing questions; calculators are allowed.', '["AO1: demonstrate knowledge and understanding of business concepts and issues","AO2: apply knowledge and understanding to business contexts","AO3: analyse business information and issues to show chains of impact","AO4: evaluate information and issues to make justified conclusions"]', '["Apply each point to the exact business, objective and data in the source","Show formula, substitution, working and units for calculations","Develop analysis through connected because and therefore chains","For justify and evaluate questions, compare realistic options and make a conditional judgement","Learn all required formulae because they are not supplied in the examination"]', 'https://qualifications.pearson.com/content/dam/pdf/GCSE/Business/2017/specification-and-sample-assessments/gcse-business-spec-2017.pdf', 'https://qualifications.pearson.com/en/qualifications/edexcel-gcses/business-2017.coursematerials.html', 0, '2026-09-28'),
  ('subject-design-technology', 'AQA GCSE Design and Technology 8552: a 2-hour, 100-mark written paper worth 50% and a substantial design-and-make NEA of approximately 30–35 hours, 100 marks and 50%. The paper assesses core, specialist, and designing and making principles; the specialist material area still needs confirming.', '["AO1: identify, investigate and outline design possibilities to address needs and wants","AO2: design and make prototypes that are fit for purpose","AO3: analyse and evaluate design decisions and outcomes, including the work of others","AO4: demonstrate and apply technical knowledge and understanding"]', '["Connect every design choice to a named user need and measurable specification point","Justify material and process choices through properties, scale, cost and sustainability","Show calculations clearly: at least 15% of the paper assesses maths and at least 10% assesses science","Use testing evidence to drive iterations instead of describing changes","Practise extended responses that compare trade-offs and reach a justified conclusion"]', 'https://www.aqa.org.uk/subjects/design-and-technology/gcse/design-and-technology-8552/specification', 'https://www.aqa.org.uk/subjects/design-and-technology/gcse/design-and-technology-8552/assessment-resources', 1, '2026-09-28')
ON CONFLICT(subject_id) DO UPDATE SET
  exam_summary = excluded.exam_summary,
  assessment_objectives_json = excluded.assessment_objectives_json,
  exam_tips_json = excluded.exam_tips_json,
  specification_url = excluded.specification_url,
  assessment_resources_url = excluded.assessment_resources_url,
  provisional = excluded.provisional,
  verified_at = excluded.verified_at,
  updated_at = CURRENT_TIMESTAMP;

DELETE FROM revision_resources WHERE subject_id IN ('subject-geography', 'subject-business', 'subject-design-technology');

